 const bgOf=el=>{while(el){const b=getComputedStyle(el).backgroundColor; if(b!=='rgba(0, 0, 0, 0)' && !b.endsWith(', 0)')) return b; el=el.parentElement;} return 'rgb(255, 255, 255)'};
 const ratio=(a,b)=>{const x=lum(a),y=lum(b); return ((Math.max(x,y)+0.05)/(Math.min(x,y)+0.05)).toFixed(2)};
 const sel=['.paginacao-anteriores .page.active','.paginacao-anteriores .page:not(.active)','.trilha-servico a','.trilha-servico [aria-current]','#cpf-apoio','.apoio-solicitacao','.table-title','th','td','.marca-govbr','.marca-govbr span','.br-skiplink a','label[for=nome]','.upload-button span','legend'];
